import sys, json, struct, secrets, socket, importlib.util
from pathlib import Path
from collections import deque
from unittest.mock import patch
ROOT=Path.cwd(); SPIKE=ROOT/'spikes/003-clientless-limbs'; sys.path.insert(0,str(SPIKE))
def load(name,path):
    spec=importlib.util.spec_from_file_location(name,path); mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod); return mod
C=load('fresh_review_client',SPIKE/'client.py')
class Clock:
    def __init__(self): self.now=100.0
    def monotonic(self): return self.now
    def sleep(self,seconds): self.now+=seconds
class Transport:
    def __init__(self,chunks=(),error=None): self.chunks=deque(chunks); self.error=error; self.closed=False; self.closes=0; self.shutdowns=0; self.owner=None; self.recv_error=None; self.close_owned_checks=0
    def settimeout(self,value): pass
    def sendall(self,value): pass
    def recv(self,n):
        if self.chunks:
            raw=self.chunks.popleft(); self.chunks.appendleft(raw[n:]) if len(raw)>n else None; return raw[:n]
        if self.recv_error is not None: raise self.recv_error
        raise AssertionError('unexpected receive')
    def shutdown(self,*a): self.shutdowns+=1
    def close(self):
        self.closes+=1
        if self.owner is not None:
            assert self in self.owner._temporary_sockets
            assert self in self.owner._handshake_buffers
            assert self in self.owner._handshake_packets
            self.close_owned_checks+=1
        if self.error is not None: raise self.error
        self.closed=True
    def __exit__(self,*args): assert args==(None,None,None); self.close()
class Reader:
    def __init__(self,error=None): self.live=True; self.error=error; self.joins=0
    def is_alive(self): return self.live
    def join(self,**kw):
        self.joins+=1
        if self.error is not None: raise self.error
        self.live=False

def frames(stage,completed,name='Offline1',aid=11,gid=21):
    if not completed:
        return C.pdb.pack(0x006a,bytes(21)) if stage=='login' else struct.pack('<I',aid)+C.pdb.pack(0x006c,b'\x01')
    if stage=='login':
        raw=bytearray(80); struct.pack_into('<HH',raw,0,0x0ac4,80); struct.pack_into('<I',raw,8,aid); raw[64:68]=bytes([127,0,0,1]); struct.pack_into('<H',raw,68,6121); return bytes(raw)
    raw=bytearray(182); struct.pack_into('<HH',raw,0,0x006b,182); struct.pack_into('<I',raw,27,gid); raw[115:139]=name.encode().ljust(24,b'\0'); raw[145]=5
    zone=bytearray(28); struct.pack_into('<HI',zone,0,0x0071,gid); zone[22:26]=bytes([127,0,0,1]); struct.pack_into('<H',zone,26,5121)
    return struct.pack('<I',aid)+bytes(raw)+bytes(zone)
def names(error):
    out=[]; tb=error.__traceback__
    while tb: out.append(tb.tb_frame.f_code.co_name); tb=tb.tb_next
    return out
results=[]
for stage in ['login','char']:
 for completed in [False,True]:
  for target in [1,2]:
   for cleanup_type in [OSError,KeyboardInterrupt,SystemExit]:
    L=load('fresh_review_limbs',SPIKE/'test_limbs.py'); clock=Clock(); budget=L.Budget(59,clock=clock.monotonic,sleep=clock.sleep)
    L.fixture={'schema':1,'isolated_disposable':True,'login_host':'127.0.0.1','login_port':6900,'accounts':[{'username':f'offline-{i}','password':secrets.token_hex(8),'character':f'Offline{i}','account_id':10+i,'char_id':20+i} for i in [1,2]]}
    cleanup=cleanup_type('PRIVATE-SYNTHETIC'); transport=Transport([frames(stage,completed,f'Offline{target}',10+target,20+target)],cleanup); attempts=[]; made=[]; origin_errors=[]; map_resources=[]
    actual_login=L.FixtureClient._login_server; actual_char=L.FixtureClient._char_server; actual_connect=L.FixtureClient.connect
    def login(bot):
        i=int(bot.user[-1]); attempts.append([clock.now,i]); made.append(bot); bot.aid=10+i; bot.gid=20+i
        if stage=='login' and i==target: transport.owner=bot; return actual_login(bot)
        return '127.0.0.1',1
    def char(bot,*args):
        if stage=='char' and int(bot.user[-1])==target: transport.owner=bot; return actual_char(bot,*args)
        return '127.0.0.1',1
    def map_stage(bot,*args):
        bot.sock=Transport(); bot.rx_thread=Reader(); map_resources.append((bot.sock,bot.rx_thread))
    def connect(bot,**kw):
        try: return actual_connect(bot,**kw)
        except BaseException as origin: origin_errors.append(origin); raise
    def limb(participants,shared): L.connect_pair(participants,shared); return 'OK synthetic'
    with patch.object(L.time,'monotonic',clock.monotonic),patch.object(L.FixtureClient,'_login_server',login),patch.object(L.FixtureClient,'_char_server',char),patch.object(L.FixtureClient,'_map_server',map_stage),patch.object(L.FixtureClient,'connect',connect),patch('socket.create_connection',lambda *a,**kw: transport):
        propagated=None
        try: L.run_limb('first',limb,budget)
        except BaseException as origin: propagated=origin
        assert attempts==[[100.0,i] for i in range(1,target+1)]
        assert budget.unreleased_clients==[made[-1]] and made[-1]._temporary_sockets==[transport]
        assert not transport.closed and transport.close_owned_checks>=3
        assert transport in made[-1]._handshake_buffers and transport in made[-1]._handshake_packets
        assert cleanup in made[-1].cleanup_errors
        assert all(s.closed and r.joins==1 and not r.live for s,r in map_resources)
        assert not any(result[1] for result in L.results)
        assert all('PRIVATE' not in result[3] for result in L.results)
        if completed:
            assert origin_errors[0] is cleanup and 'close' in names(cleanup)
            if cleanup_type is not OSError: assert propagated is cleanup
        else:
            assert isinstance(origin_errors[0],RuntimeError)
            assert ('_login_server' if stage=='login' else '_char_server') in names(origin_errors[0])
            assert propagated is None
        assert all('PRIVATE' not in n for n in getattr(origin_errors[0],'__notes__',[]))
        clock.sleep(30); L.run_limb('later',limb,budget)
        try: L.connect_pair([],budget)
        except RuntimeError: pass
        else: raise AssertionError('direct pair bypass')
        assert attempts==[[100.0,i] for i in range(1,target+1)]
        transport.error=None; made[-1].close(); count=transport.closes; made[-1].close(); assert count==transport.closes
        assert transport.closed and not made[-1]._temporary_sockets and not made[-1]._handshake_buffers and not made[-1]._handshake_packets
        L.run_limb('after-manual-release',limb,budget); assert len(attempts)==target and not L.results[-1][1]
    results.append({'kind':'actual-fixture-harness','stage':stage,'completed':completed,'participant':target,'cleanup':cleanup_type.__name__,'attempts':attempts,'cleanup_attempts':count,'origin_identity_verified':completed,'handshake_traceback_retained':True,'blocked_retry_later_pass':True,'eventual_release_idempotent':True,'poison_survives_manual_release':True})
for stage in ['login','char']:
 for origin_type in [ValueError,KeyboardInterrupt,SystemExit]:
  for cleanup_type in [OSError,KeyboardInterrupt,SystemExit]:
    bot=C.BotClient('offline',secrets.token_hex(8),verbose=False); bot.aid=11
    origin=origin_type('PRIVATE-ORIGIN'); cleanup=cleanup_type('PRIVATE-CLEANUP'); transport=Transport([struct.pack('<I',11)] if stage=='char' else [],cleanup); transport.owner=bot; transport.recv_error=origin
    with patch('socket.create_connection',lambda *a,**k:transport),patch.object(bot,'_login_server',bot._login_server if stage=='login' else lambda:('127.0.0.1',1)):
        try: bot.connect()
        except BaseException as caught:
            assert caught is origin and 'recv' in names(caught)
            assert all('PRIVATE' not in note for note in getattr(caught,'__notes__',[]))
        else: raise AssertionError('missing origin')
        assert bot._temporary_sockets==[transport] and cleanup in bot.cleanup_errors
    transport.error=None; bot.close(); bot.close()
    results.append({'kind':'origin-identity-traceback','stage':stage,'origin':origin_type.__name__,'cleanup':cleanup_type.__name__,'passed':True})
# Multiple temporary transports, shutdown, map close and reader join all fail independently.
bot=C.BotClient('offline',secrets.token_hex(8),verbose=False)
temps=[Transport(error=KeyboardInterrupt()),Transport(error=SystemExit())]
bot._temporary_sockets.extend(temps); bot.sock=Transport(error=KeyboardInterrupt()); bot.rx_thread=Reader(SystemExit())
map_sock=bot.sock; reader=bot.rx_thread; calls=[]
def interrupted_shutdown(*a): calls.append('shutdown'); raise SystemExit()
map_sock.shutdown=interrupted_shutdown
try: bot.close()
except RuntimeError: pass
else: raise AssertionError('cleanup failure swallowed')
assert [t.closes for t in temps]==[1,1] and map_sock.closes==1 and reader.joins==1 and calls==['shutdown']
assert bot._temporary_sockets==temps and bot.sock is map_sock and bot.rx_thread is reader
for t in temps: t.error=None
map_sock.error=None; map_sock.shutdown=lambda *a:None; reader.error=None
bot.close(); counts=[t.closes for t in temps]+[map_sock.closes,reader.joins]; bot.close(); assert counts==[t.closes for t in temps]+[map_sock.closes,reader.joins]
assert not bot._temporary_sockets and bot.sock is None and bot.rx_thread is None
results.append({'kind':'all-owned-resources-baseexceptions','temporary_count':2,'shutdown_close_join_attempted':True,'eventual_release_idempotent':True})
# Local unconnected native socket only: no bind/connect/listen or traffic.
bot=C.BotClient('offline',secrets.token_hex(8),verbose=False); native=socket.socket(); assert native.fileno()>=0; bot._temporary_sockets.append(native); bot.close(); assert native.fileno()==-1 and not bot._temporary_sockets; bot.close()
results.append({'kind':'native-unconnected-context-release','descriptor_closed':True,'bind_connect_listen_calls':0})
print('RESULT_JSON='+json.dumps({'passed':True,'cases':results,'case_count':len(results),'external_network_calls':0}))
